-- CA_0146_la_trustee_area_boards_batch2.sql
-- LA-County TRUSTEE-AREA unified school boards, batch 2: ABC, Bonita, Burbank, Claremont.
-- Same pattern as CA_0144 (batch 1): one X0002 polygon + SCHOOL sub-district per trustee area,
-- dissolved from the LA County Registrar-Recorder precinct layer (Political_Boundaries/MapServer/34,
-- DST_USD/DIV_USD; USD codes 1 ABC, 19 Bonita, 46 Burbank, 6 Claremont); the generic 'Board Member'
-- offices move off the whole-district row; stale holders closed (how_ended 'unknown', end date not
-- researched); current members seated from each district's own board page; Nov 3 2026 area races.
--
-- BATCH-SPECIFIC:
--   * Armond Aghakhanian (Burbank TA 5) was the one DB holder who IS a current member: his row and
--     his open term are KEPT, and his office is pinned to Trustee Area 5.
--   * Four members reuse existing politician rows (campaign-finance links): Letty Mendoza (ABC TA 1,
--     'Leticia' on the board page), Brittany Allison (Bonita TA 5), Emily Weisberg (Burbank TA 2),
--     Aghakhanian.
--   * Steven Llanusa's office is pinned to Claremont TA 4, so closing his stale term the day before
--     Alex McDonald's 8/2023 start matches the real handover.
--   * Appointees start on their appointment date: Jean McHatton (ABC TA 5, 2025-04-26), Kelsey Olson
--     (Burbank TA 3, oath 2025-10-16), Alex McDonald (Claremont TA 4, 2023-08, precision month).
--   * ABC TA 5 is a SPECIAL election for the unexpired term to Dec 2028 (McHatton vs Ferrer).
--   * Vivian Malauulu (Long Beach USD trustee) held an ABC seat in the DB: that one term row is
--     DELETED, not closed (see step 4b).
--
-- IDEMPOTENT: every insert NOT EXISTS-guarded; office moves guarded on the whole-district row;
-- stale-term closing only touches open terms not held by the named member.
BEGIN;

CREATE TEMP TABLE _seat (parent_geo text, geo_id text, label text, ta text, ord int, full_name text, first_name text,
                         last_name text, url text, existing_pid uuid, term_start date, prec text, how text, src text,
                         pin_office uuid, pid uuid) ON COMMIT DROP;
